package kr.or.arte.seal.statistics.application;
import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class StatisticsQueryServiceTest {@Test void rejectsReverseAndMoreThanOneYearPeriods(){StatisticsQueryService service=new StatisticsQueryService((actor,from,to)->new StatisticsSnapshot(List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of()));UUID actor=UUID.randomUUID();assertThatThrownBy(()->service.query(actor,LocalDate.of(2026,8,2),LocalDate.of(2026,8,1))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->service.query(actor,LocalDate.of(2025,1,1),LocalDate.of(2026,1,2))).isInstanceOf(IllegalArgumentException.class);}@Test void returnsPiiFreeCountOnlySnapshot(){var expected=new StatisticsSnapshot(List.of(new StatusCount("COMPLETED",3)),List.of(new StatusCount("SUBMITTED",2)),List.of(),List.of(new StatusCount("SMTP_ACCEPTED",2)),List.of(),List.of(),List.of(),List.of(),List.of(),List.of());var service=new StatisticsQueryService((a,f,t)->expected);var result=service.query(UUID.randomUUID(),LocalDate.of(2026,8,1),LocalDate.of(2026,8,24));assertThat(result).isEqualTo(expected);assertThat(result.responses()).extracting(StatusCount::status).containsExactly("SUBMITTED");assertThat(result.mail()).extracting(StatusCount::status).containsExactly("SMTP_ACCEPTED");}

@Test void currentWorkIncludesItemsCreatedMoreThanThirtyDaysAgo(){UUID actor=UUID.randomUUID();LocalDate today=LocalDate.of(2026,9,6);List<LocalDate> dates=new ArrayList<>();var expected=new StatisticsSnapshot(List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of(new StatusCount("OVERDUE",1)),List.of(),List.of());StatisticsQueryService service=new StatisticsQueryService((a,f,t)->{dates.add(f);dates.add(t);return expected;});assertThat(service.queryCurrentWork(actor,today)).isEqualTo(expected);assertThat(dates).containsExactly(LocalDate.of(2000,1,1),today);}}
